import time
import math
from heapq import heappush
from typing import List

class Group:
    def __init__(self, sortedIntervals: List[List[int]], depth=1):
        self.minStart=1e9
        self.groups = [] # [left, end, interval_list ]
        self.depth =depth

        maxEnd=0
        totalSize=0

        for i in sortedIntervals:
            self.minStart = min(self.minStart, i[0])
            maxEnd = max(maxEnd, i[1])
            totalSize += (i[1] - i[0] + 1)

        avgSize = totalSize // len(sortedIntervals)
        # gaps = [100, 1000, 10_000, 100_000, 1_000_000]     
        # self.gap = 10

        # # maxEnd: 1e7
        # for g in gaps:
        #     if maxEnd - self.minStart > g:
        #         self.gap = g
        
        self.gap = max((maxEnd - self.minStart+1)//50, 10)

        splitGroupAgain = True
        if (maxEnd-self.minStart + 1) // avgSize < 10:
            self.gap = max((maxEnd - self.minStart+1)//20, 10)
            splitGroupAgain = False

        
        start = self.minStart
        while start <= maxEnd:
            self.groups.append({"left":start-self.minStart, "right":start+self.gap-1-self.minStart, "intervalList":[]} )
            start = start + self.gap
        # print(f"self.minStart={self.minStart} maxEnd={maxEnd} groups={groups}")    

        # put interval items into each group
        for i in sortedIntervals:
            leftIdx = math.floor((i[0] - self.minStart)/self.gap)
            rightIdx = math.floor((i[1] - self.minStart)/self.gap)
            # print(f"  i={i} leftIndex={leftIdx} rightIdx={rightIdx}")
            for n in range(leftIdx, rightIdx+1):
                self.groups[n]["intervalList"].append(i)

        # split groups again
        # print(f"    depth={self.depth} gap={self.gap} len(groups)={len(self.groups)} avg group size={len(sortedIntervals)/len(self.groups)} avgSize={avgSize:,} span={maxEnd-self.minStart:,}")
        for grp in self.groups:
            # print(f"    group len={len(grp["intervalList"])}")
            if splitGroupAgain and self.depth < 2 and self.gap > 1000 and len(grp["intervalList"]) > 1000:
                grp["node"] = Group(grp["intervalList"], self.depth+1)        


    def findInterval(self, q) -> int:
        grpIndex = math.floor((q - self.minStart)/self.gap)
        # print(f"   q={q} grpIndex={grpIndex} minStart={self.minStart} gap={self.gap} groups={len(self.groups)}")
        if(grpIndex<0 or grpIndex>=len(self.groups)):
            return -1

        grp = self.groups[grpIndex]

        node = grp.get("node")
        if node == None:
            result = -1
            hop = 0
            for x in grp["intervalList"]:
                if x[0] <= q and q <= x[1]:
                    result = x[3]
                    break

            # print(f"   hop={hop} q={q} grpIndex={grpIndex} minStart={self.minStart} gap={self.gap} groups={len(self.groups)}")
            return result
        else:
            return node.findInterval(q)    

        

class Solution:
    def minInterval(self, intervals: List[List[int]], queries: List[int]) -> List[int]:
        index = 0
        minStart=1e9
        maxEnd=0

        for i in intervals:
            i.append(index) # append a unique id
            i.append(i[1] - i[0] + 1) # append size
            index += 1
            minStart = min(minStart, i[0])
            maxEnd = max(maxEnd, i[1])

        t1 = int(time.time() * 1000)
        intervals.sort(key=lambda item: item[1]) # sort by right end    
        t2 = int(time.time() * 1000)
        print(f"sort duration = {t2 - t1:,} ms")

        queryList = [{"q": v, "idx": idx, "minHeap": []} for idx, v in enumerate(queries)]
        queryList.sort(key=lambda x: x["q"])

        headIdx = 0 # head index to intervals
        for i in range(len(queryList)):
            q = queryList[i]
            # nextQ = -1 
            # if i < len(queryList) - 1:
            #     nextQ = queryList[i+1]["q"]
            
            # get candidate intervals for q
            print(f"   i={i} search candidate interval headIdx={headIdx}")
            j = headIdx
            jspan = 0
            headSpan = 0
            while j < len(intervals):
                interval = intervals[j]
                j += 1
                jspan += 1

                if interval[1] < q["q"]:
                    headIdx = j  # items before headIdx is useless for remaining queries
                    headSpan += 1

                elif q["q"] <= interval[1]:
                    if interval[0] <= q["q"]:
                        # add interval[1] - interval[0] +1 to minHeap
                        heappush(q["minHeap"], interval[1] - interval[0] + 1)

            print(f"    jspan={jspan} headSpan={headSpan}")
        # theGrp = Group(intervals)        
        # print(f"    interval size={len(intervals):,} queries size={len(queries):,}")
        
        queryList.sort(key=lambda item: item["idx"])
        return [ item["minHeap"][0] if len(item["minHeap"])>0 else -1 for item in queryList]
        # result = []
        # for q in queryList:

        # for q in queries:
        #     size = theGrp.findInterval(q)
        #     result.append(size)

        # return result

